export interface BirthInfo {
    year: number;
    month: number;
    day: number;
    hour: number;
    minute: number;
    isLunar: boolean;
    isLeapMonth?: boolean;
    gender: 'male' | 'female';
    timeZone: number;
    longitude?: number;
    useTrueSolarTime?: boolean;
}
export interface CalculationMetadata {
    inputCalendar: 'solar' | 'lunar';
    inputDateTime: string;
    civilSolarDateTime: string;
    effectiveSolarDateTime: string;
    effectiveLunarDate: {
        year: number;
        month: number;
        day: number;
        isLeapMonth: boolean;
    };
    timeZone: number;
    longitude?: number;
    trueSolarTimeApplied: boolean;
    correctionMinutes: number;
}
export type Tiangan = '甲' | '乙' | '丙' | '丁' | '戊' | '己' | '庚' | '辛' | '壬' | '癸';
export type Dizhi = '子' | '丑' | '寅' | '卯' | '辰' | '巳' | '午' | '未' | '申' | '酉' | '戌' | '亥';
export interface GanZhi {
    gan: Tiangan;
    zhi: Dizhi;
}
export interface SiZhu {
    year: GanZhi;
    month: GanZhi;
    day: GanZhi;
    hour: GanZhi;
}
export type ShiShen = '比肩' | '劫财' | '食神' | '伤官' | '偏财' | '正财' | '七杀' | '正官' | '偏印' | '正印';
export interface LiuNian {
    year: number;
    age: number;
    ganZhi: GanZhi;
}
export interface DayunDetail {
    ganZhi: GanZhi;
    startAge: number;
    endAge: number;
    startYear: number;
    endYear: number;
    ganShiShen: ShiShen;
    zhiShiShen: ShiShen;
    liuNian: LiuNian[];
}
export interface BaziChart {
    birthInfo: BirthInfo;
    calculation: CalculationMetadata;
    siZhu: SiZhu;
    dayMaster: Tiangan;
    shiShen: Record<'year' | 'month' | 'day' | 'hour', ShiShen>;
    zhangSheng?: Record<'year' | 'month' | 'day' | 'hour', string>;
    naYin?: Record<'year' | 'month' | 'day' | 'hour', string>;
    dayunStart: number;
    dayun: DayunDetail[];
}
